/// <summary>
/// PaffH 19.10.22
/// AX2009: forms.NDX_ProdIdent.setProdIdentStatusFilter
/// </summary>
/// <param name = "_filterValue"></param>
/// <param name = "lSet"></param>
public void setFilterProdIdentStatus(NDXProdIdentStatus _filterValue, boolean _lSet)
{

    InventTable_1_DS.query().dataSourceTable(tablenum(InventTable)).clearRange(fieldnum(InventTable, NDX_ProdIdentStatus));

    if(_lSet)
    {
        InventTable_1_DS.query().dataSourceTable(tablenum(InventTable)).addRange(fieldnum(InventTable, NDX_ProdIdentStatus)).value(QueryValue(_filterValue));
    }

    InventTable_1_DS.executeQuery();
}

/// <summary>
/// PaffH 26.11.24
/// see: forms.DocuType.class.ActionClassName 
/// </summary>
private void lookUpActionClassName(FormControl _callingControl)
{
    SysTableLookup          sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpIdRef), _callingControl);
    Query                   query           = new Query();
    QueryBuildDataSource    qbds;

    sysTableLookup.addLookupfield(fieldnum(TmpIdRef, HelpTxt));
    sysTableLookup.setLabel("@SYS7576"); // Description
    sysTableLookup.addLookupfield(fieldnum(TmpIdRef, Name), true);
    sysTableLookup.setLabel("@SYS24724"); // Class name
    // Content of the table is taken from AOT metadata
    //BP deviation documented
    sysTableLookup.parmTmpBuffer(tmpIdRef);
    qbds = query.addDataSource(tablenum(TmpIdRef));
    qbds.addSortField(fieldnum(TmpIdRef, HelpTxt));
    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();
}

