/// <summary>
/// PaffH 14.03.23
/// if necessary append NDXProdIdentProcedureTable
/// </summary>
/// <param name = "_append">boolean</param>
public void create(boolean _append = false)
{
    super(_append);

    if (NDXProdIdentProcedureTable_1.RecId == 0)
    {
        NDXProdIdentProcedureTable_1.initFromNDXProdIdentProcedureLine1(NDXProdIdentProcedureLine1_1);
        NDXProdIdentProcedureTable_1.InventTable = InventTable_1.RecId;
        NDXProdIdentProcedureTable_1.write();
        NDXProdIdentProcedureTable_1_ds.reread();
        NDXProdIdentProcedureTable_1_ds.refresh();
    }
    NDXProdIdentProcedureLine1_1.NDXProdIdentProcedureTable = NDXProdIdentProcedureTable_1.RecId;
}

/// <summary>
/// PaffH 14.03.23
/// get next IDSort
/// </summary>
public void initValue()
{
    super();

    NDXProdIdentProcedureLine2 nDXProdIdentProcedureLine2Local;
    select firstonly IdSort from nDXProdIdentProcedureLine2Local
        order by IDSort desc
        where nDXProdIdentProcedureLine2Local.NDXProdIdentProcedureLine1 == NDXProdIdentProcedureLine1_1.RecId;
    NDXProdIdentProcedureLine2_1.IDSort = nDXProdIdentProcedureLine2Local.IDSort + 1;
}

