/// <summary>
/// PaffH 06.01.24
/// </summary>
/// <param name = "_formControl">FormControl</param>
/// <param name = "_filterStr">str</param>
public void lookup(FormControl _formControl, str _filterStr)
{
    //super(_formControl, _filterStr);
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tablenum(NDXProdIdentBlockLine), _formControl);
    Query                   query;
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildRange         qr;

    sysTableLookup.addLookupfield(fieldnum(NDXProdIdentBlockLine, Name));

    query = new Query();
    queryBuildDataSource = query.addDataSource(tablenum(NDXProdIdentBlockLine));

    qr = queryBuildDataSource.addRange(fieldnum(NDXProdIdentBlockLine, NDXProdIdentBlockTable));
    qr.value(queryValue(NDXProdIdentBlock2ItemId_1.NDXProdIdentBlockTable));
    qr.status(RangeStatus::Hidden);

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

